      scrollContainerRef.current = el;

      if (el) {
        el.addEventListener("scroll", checkAndLoadMore, { passive: true });
        checkAndLoadMore();
      }
    }, 100);

    return () => {
      clearTimeout(timeoutId);
      const el = scrollContainerRef.current;
      if (el) {
        el.removeEventListener("scroll", checkAndLoadMore);
