      noIndex: metadata.noIndex,
      path: metadata.path,
      type: metadata.type,
    }),
    links:
      metadata.path && !metadata.noIndex
        ? [{ rel: "canonical", href: absoluteUrl(metadata.path) }]
        : [],
  };
}

