          <Image
            src={sourceThumbnail}
            alt={sourceTitle}
            fill
            sizes="64px"
            className="object-cover"
            unoptimized
          />
        ) : (
          <div className="flex size-full items-center justify-center">
            <ThumbnailIcon className="text-muted-foreground size-4" />
          </div>
        )}
      </div>
      <div className="min-w-0 flex-1">
